// Shrinks the theme stylesheet (public/assets/css/carryon-style.css).
//
// The WordPress theme's compiled CSS contains selectors for menus nested
// 4-12 levels deep (".sub-menu > li > .sub-menu > li > ..."), generated by a
// Sass loop. No page on this site has menus that deep, but every visitor's
// browser had to download and parse them (3.6 MB). This removes only those
// selectors and minifies the result - every other rule keeps its meaning.
//
//   node tools/slim-css.mjs
import fs from 'node:fs';
import postcss from 'postcss';
import { transformSync } from 'esbuild';

const file = new URL('../public/assets/css/carryon-style.css', import.meta.url);
const MAX_DEPTH = 3; // keep selectors with up to three nested .sub-menu / .children levels

const depth = (selector) => (selector.match(/\.(sub-menu|children)\b/g) || []).length;

const before = fs.readFileSync(file, 'utf8');
const root = postcss.parse(before);
let dropped = 0;

root.walkRules((rule) => {
  const kept = rule.selectors.filter((s) => depth(s) <= MAX_DEPTH);
  if (kept.length === rule.selectors.length) return;
  dropped += rule.selectors.length - kept.length;
  if (kept.length) rule.selectors = kept;
  else rule.remove();
});

const after = transformSync(root.toString(), { loader: 'css', minify: true }).code;
fs.writeFileSync(file, after);
const kb = (s) => Math.round(Buffer.byteLength(s) / 1024) + ' KB';
console.log(`dropped ${dropped} selectors: ${kb(before)} -> ${kb(after)}`);
